import whisper
import json

# Load the tiny model for fast transcription
model = whisper.load_model('tiny')

# Transcribe with word timestamps
result = model.transcribe('/root/input.mp4', word_timestamps=True, language='en')

# Filler words to detect
filler_words = {
    'um', 'uh', 'hum', 'hmm', 'mhm', 'like', 'you know', 'i mean', 'yeah', 'so', 'kind of', 'basically', 'i guess', 'well', 'okay'
}

# Phrases (multi-word)
phrases = ['you know', 'i mean', 'kind of', 'basically', 'i guess']

# Extract words and find fillers
words = []
fillers = []

for segment in result['segments']:
    if 'words' in segment:
        segment_words = []
        for word_info in segment['words']:
            word = word_info['word'].strip()
            start = word_info['start']
            segment_words.append({
                'word': word,
                'start': start
            })

        # Check single words
        for word_data in segment_words:
            word_lower = word_data['word'].lower()
            clean_word = ''.join(c for c in word_lower if c.isalnum())

            if clean_word in ['um', 'uh', 'hum', 'hmm', 'mhm', 'like', 'so', 'well', 'yeah', 'okay', 'basically', 'guess']:
                fillers.append({
                    'word': word_data['word'].lower(),
                    'timestamp': round(word_data['start'], 2)
                })

        # Check for multi-word phrases
        text = ' '.join([w['word'] for w in segment_words]).lower()

        for phrase in phrases:
            if phrase in text:
                # Find the first word of the phrase
                words_in_phrase = phrase.split()
                first_word_start = None
                for i, word_data in enumerate(segment_words):
                    if word_data['word'].lower() == words_in_phrase[0]:
                        # Check if it's the start of the phrase
                        remaining_phrase = ' '.join([w['word'].lower() for w in segment_words[i:i+len(words_in_phrase)]])
                        if remaining_phrase.startswith(phrase):
                            first_word_start = word_data['start']
                            break
                if first_word_start is not None:
                    fillers.append({
                        'word': phrase,
                        'timestamp': round(first_word_start, 2)
                    })

# Save to JSON
with open('/root/annotations.json', 'w') as f:
    json.dump(fillers, f, indent=2)

print(f'Found {len(fillers)} filler words/phrases')
print(json.dumps(fillers[:10], indent=2))
"

