import whisper
import json

# Load the tiny model for fast transcription
print('Loading Whisper model...')
model = whisper.load_model('tiny')

# Transcribe with word timestamps
print('Transcribing video...')
result = model.transcribe('/root/input.mp4', word_timestamps=True, language='en')

# Filler words to detect
filler_words = {
    'um', 'uh', 'hum', 'hmm', 'mhm', 'like', 'you know', 'i mean', 'yeah', 'so', 'kind of', 'basically', 'i guess', 'well', 'okay'
}

# Extract words and find fillers
fillers = []

for segment in result['segments']:
    if 'words' in segment:
        # Check for single words first
        for word_info in segment['words']:
            word_lower = word_info['word'].strip().lower()
            # Remove punctuation for matching
            clean_word = ''.join(c for c in word_lower if c.isalnum())

            # Check against filler words (single words only here)
            if clean_word in ['um', 'uh', 'hum', 'hmm', 'mhm', 'like', 'so', 'well', 'yeah', 'okay', 'basically', 'guess']:
                fillers.append({
                    'word': word_info['word'].strip(),
                    'timestamp': round(word_info['start'], 2)
                })

        # Check for multi-word phrases
        segment_text = segment['text'].lower()

        # Check for phrases
        phrases = ['you know', 'i mean', 'kind of', 'basically', 'i guess']
        for phrase in phrases:
            if phrase in segment_text:
                # Find the timestamp of the first word in the phrase
                words_in_phrase = phrase.split()
                for word_info in segment['words']:
                    if word_info['word'].strip().lower() == words_in_phrase[0]:
                        # Verify this is the start of the phrase
                        following_words = []
                        for i, w in enumerate(segment['words']):
                            if i >= segment['words'].index(word_info):
                                following_words.append(w['word'].strip().lower())
                                if len(following_words) >= len(words_in_phrase):
                                    break

                        if ' '.join(following_words[:len(words_in_phrase)]) == phrase:
                            fillers.append({
                                'word': phrase,
                                'timestamp': round(word_info['start'], 2)
                            })
                        break

# Sort by timestamp
fillers.sort(key=lambda x: x['timestamp'])

# Save to JSON
with open('/root/annotations.json', 'w') as f:
    json.dump(fillers, f, indent=2)

print(f'Found {len(fillers)} filler words/phrases')
print('\\nFirst 10 detections:')
for filler in fillers[:10]:
    print(f\"  {filler['word']:15s} at {filler['timestamp']:.2f}s\")
"

